using RvtIO.Internal;
using RvtIO.Parsing;
using Xunit;

namespace RvtIO.Tests;

/// <summary>Faces of a wall GRep come from the EdgeLoops of the live Faces, not from every Edge that names a Face.</summary>
public class WallFaceLoopTests
{
    // GElement block of the wall 746589 of Test_2022 (a 300 mm retaining wall with a horizontal groove). Its Geometry holds
    // twelve Faces: six live ones (flags 0x88204/0x88604, each with one EdgeLoop) and six that remain from the groove cut
    // (flags 0x8204, no EdgeLoop). Of the 99 Edges only those on the loops of the live Faces are shell edges; the others
    // name a dead Face and would give the live Faces a second, smaller cycle. The wall is written as a 5-vertex extrusion of the plan
    // (the groove is not exported).
    private const string Fixture = "";

    // GElement block of the wall 422243 of Test_2022 (a partition with a doorway). Faces 26 and 28 (the end faces of the
    // doorway) each list two m_faceRegions sub-faces (139, 140 and 145, 146); Faces 21, 23 and 25 are dead.
    private const string SplitFaceFixture = "";

    // Face handles of the live Faces, in the order of the block.
    private static readonly uint[] LiveFaces = [12, 13, 14, 16, 18, 19];

    private static GRepData Decode(byte[] block) =>
        Assert.IsType<GRepData>(GRepParserV2.Parse(block, 0, BitConverter.ToUInt32(block, 8)));

    private static double Area(GRepFace face)
    {
        var ring = face.Vertices!;
        double x = 0, y = 0, z = 0;
        for (int i = 0; i < ring.Count; i++)
        {
            var a = ring[i];
            var b = ring[(i + 1) % ring.Count];
            x += a[1] * b[2] - a[2] * b[1];
            y += a[2] * b[0] - a[0] * b[2];
            z += a[0] * b[1] - a[1] * b[0];
        }
        return 0.5 * Math.Sqrt(x * x + y * y + z * z);
    }

    [Fact]
    public void LiveFacesFollowTheirLoops_DeadFacesAreDropped()
    {
        var geometry = Decode(Convert.FromBase64String(Fixture));

        Assert.Equal(LiveFaces, geometry.Faces.Select(face => face.SourceFace).Order());
        // South and north sides, bottom, top, mitred end and square end of a 17.75 ft x 0.98 ft x 8.53 ft wall.
        double[] expected = [136.855, 151.399, 16.626, 16.626, 16.792, 8.394];
        var areas = geometry.Faces.OrderBy(face => face.SourceFace).Select(Area).ToArray();
        for (int i = 0; i < expected.Length; i++) Assert.Equal(expected[i], areas[i], tolerance: 0.01);
        var solid = Assert.Single(geometry.Solids);
        Assert.True(solid.IsClosed);
        Assert.Equal(6, solid.FaceIndices.Count);
    }

    [Fact]
    public void BrokenLoopLink_FallsBackToTheEdgesOfTheFace()
    {
        byte[] block = Convert.FromBase64String(Fixture);
        // EdgeLoop 127 (Face 12): m_pFace 12, m_next 24, m_prev 72. A last edge that is not the one the chain ends on
        // makes the loop untrustworthy, so Face 12 is rebuilt from all the Edges that name it, as before.
        byte[] tail = [12, 0, 0, 0, 24, 0, 0, 0, 72, 0, 0, 0];
        int at = block.AsSpan().IndexOf(tail);
        Assert.True(at > 0);
        Assert.Equal(-1, block.AsSpan(at + 1).IndexOf(tail));
        block[at + 8] = 73;

        var geometry = Decode(block);
        var south = geometry.Faces.Where(face => face.SourceFace == 12).ToList();
        Assert.Single(south);
        Assert.True(Area(south[0]) < 10, "the neighbour-based search finds the groove strip, not the whole side");
        Assert.DoesNotContain(geometry.Faces, face => face.SourceFace is 15 or 17 or 20 or 21 or 22 or 23);
    }

    // Edge 72 closes the loop of Face 12 at the start of Edge 24. Its end point (u, v) is moved along v: the loop stays
    // one ring while the miss is below the vertex tolerance (0.000523 ft), and is not trusted above it.
    [Theory]
    [InlineData(0.0003, true)]
    [InlineData(0.001, false)]
    public void LoopEdgesMeetOnlyWithinTheVertexTolerance(double miss, bool ring)
    {
        byte[] block = Convert.FromBase64String(Fixture);
        byte[] edge72 = new byte[64];
        double[] values = [-7.1054273576010019E-15, 4.4291338582677158, -17.224409448818875, 4.4291338582677158,
            -7.1054273576010019E-15, 0.0, -17.224409448818875, 0.0];
        for (int i = 0; i < values.Length; i++) BitConverter.GetBytes(values[i]).CopyTo(edge72, 8 * i);
        int at = block.AsSpan().IndexOf(edge72);
        Assert.True(at > 0);
        Assert.Equal(-1, block.AsSpan(at + 1).IndexOf(edge72));
        BitConverter.GetBytes(miss).CopyTo(block, at + 32 + 8);

        var geometry = Decode(block);
        double area = Area(Assert.Single(geometry.Faces, face => face.SourceFace == 12));
        if (ring) Assert.Equal(136.855, area, tolerance: 0.05);
        else Assert.True(area < 10, "beyond the tolerance the loop is not trusted and the neighbour-based search runs");
    }

    [Fact]
    public void SplitFaceRegions_AreNotFacesOfTheShell()
    {
        var geometry = Decode(Convert.FromBase64String(SplitFaceFixture));

        // Face 20 (the bottom) is two disjoint regions of one Face. Sub-faces 139, 140, 145 and 146 repeat parts of the
        // end faces and are not Faces of the shell; the dead Faces 21, 23 and 25 have no boundary.
        Assert.Equal(new uint[] { 18, 19, 20, 20, 22, 24, 26, 27, 28, 29 }, geometry.Faces.Select(face => face.SourceFace).Order());
        var solid = Assert.Single(geometry.Solids);
        Assert.True(solid.IsClosed);
        Assert.Equal(10, solid.FaceIndices.Count);
    }
}
